const signupFormSchema = z.object({
  firstName: z.string().min(1, 'First name is required'),
  lastName: z.string().min(1, 'Last name is required'),
  email: z.string().email('Invalid email address'),
  phone: z.string().min(10, 'Phone number must be at least 10 digits'),
  password: z.string().min(6, 'Password must be at least 6 characters'),
});

type SignupFormValues = z.infer<typeof signupFormSchema>;

export default function SignupPage() {
  const { register: authRegister } = useAuth();
  const navigate = useNavigate();

  const form = useForm<SignupFormValues>({
    resolver: zodResolver(signupFormSchema),
    defaultValues: {
      firstName: '',
      lastName: '',
      email: '',
      phone: '',
      password: '',
    },
  });

  const onSubmit = async (values: SignupFormValues): Promise<void> => {
    try {
      await authRegister(values);
      toast.success('Account created successfully! Please log in.');
      navigate(ROUTES.LOGIN);
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : 'Failed to create account.';
      toast.error(errorMessage);
    }
  };

  return (
    <section className="py-12 px-4">
      <div className="max-w-md mx-auto bg-white p-8 rounded-lg shadow-md border border-gray-100">
        <h1 className="text-3xl font-bold text-center mb-6 text-[#212121]">
          Create Your Account
        </h1>
        <Form {...form}>
          <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
            <FormField
              control={form.control}
              name="firstName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>First Name</FormLabel>
                  <FormControl>
                    <Input
                      placeholder="John"
                      {...field}
                      className="border border-gray-300 rounded-md px-4 py-2 focus:ring-2 focus:ring-[#E87A00] focus:border-transparent"
                      data-testid="signup-firstName"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="lastName"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Last Name</FormLabel>
                  <FormControl>
                    <Input
                      placeholder="Doe"
                      {...field}
                      className="border border-gray-300 rounded-md px-4 py-2 focus:ring-2 focus:ring-[#E87A00] focus:border-transparent"
                      data-testid="signup-lastName"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="email"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Email</FormLabel>
                  <FormControl>
                    <Input
                      type="email"
                      placeholder="john.doe@example.com"
                      {...field}
                      className="border border-gray-300 rounded-md px-4 py-2 focus:ring-2 focus:ring-[#E87A00] focus:border-transparent"
                      data-testid="signup-email"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="phone"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Phone Number</FormLabel>
                  <FormControl>
                    <Input
                      type="tel"
                      placeholder="9876543210"
                      {...field}
                      className="border border-gray-300 rounded-md px-4 py-2 focus:ring-2 focus:ring-[#E87A00] focus:border-transparent"
                      data-testid="signup-phone"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <FormField
              control={form.control}
              name="password"
              render={({ field }) => (
                <FormItem>
                  <FormLabel>Password</FormLabel>
                  <FormControl>
                    <Input
                      type="password"
                      placeholder="********"
                      {...field}
                      className="border border-gray-300 rounded-md px-4 py-2 focus:ring-2 focus:ring-[#E87A00] focus:border-transparent"
                      data-testid="signup-password"
                    />
                  </FormControl>
                  <FormMessage />
                </FormItem>
              )}
            />
            <Button
              type="submit"
              className="w-full bg-[#E87A00] hover:bg-[#D46B00] text-white font-semibold rounded-md px-6 py-3 transition-all duration-200"
              disabled={form.formState.isSubmitting}
              data-testid="signup-submit"
            >
              {form.formState.isSubmitting ? 'Creating Account...' : 'Sign Up'}
            </Button>
          </form>
        </Form>
        <p className="text-center text-sm text-gray-600 mt-4">
          Already have an account?{' '}
          <Link to={ROUTES.LOGIN} className="text-[#E87A00] hover:underline">
            Log In
          </Link>
        </p>
      </div>
    </section>
  );
}

import { useState } from 'react';
import { useAdminGetAllOrders, useUpdateOrderStatus } from '@/hooks/orderHooks';
import { OrderStatus, OrderResponse } from '@/types/order';
import { OrderTable } from '@/components/admin/order/OrderTable';
import { toast } from 'sonner';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { OrderStatusValues } from '@/types/order';

export default function AdminOrdersPage() {
  const { data: orders, isLoading, isError, error } = useAdminGetAllOrders();
  const { mutate: updateOrderStatusMutation, isPending: isUpdatingStatus } = useUpdateOrderStatus();
  const [filterStatus, setFilterStatus] = useState<OrderStatus | 'ALL'>('ALL');

  const handleUpdateStatus = (order: OrderResponse, newStatus: OrderStatus): void => {
    updateOrderStatusMutation(order.id, {
      onSuccess: () => {
        toast.success(`Order ${order.id} status updated to ${newStatus}`);
      },
      onError: (err) => {
        toast.error(`Failed to update order status: ${err.message}`);
      },
    });
  };

  const filteredOrders = orders?.filter(order =>
    filterStatus === 'ALL' || order.status === filterStatus
  ) || [];

  if (isLoading) {
    return (
      <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <h1 className="text-2xl md:text-3xl font-semibold text-[#212121] mb-6">Order Management</h1>
        <p>Loading orders...</p>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <h1 className="text-2xl md:text-3xl font-semibold text-[#212121] mb-6">Order Management</h1>
        <p className="text-red-500">Error loading orders: {error?.message}</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
      <h1 className="text-2xl md:text-3xl font-semibold text-[#212121] mb-6">Order Management</h1>

      <div className="mb-4 flex justify-end">
        <Select
          onValueChange={(value: OrderStatus | 'ALL') => setFilterStatus(value)}
          value={filterStatus}
        >
          <SelectTrigger className="w-[180px]">
            <SelectValue placeholder="Filter by Status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="ALL">All Statuses</SelectItem>
            {OrderStatusValues.map((status) => (
              <SelectItem key={status} value={status}>
                {status}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <div className="bg-white rounded-lg shadow-sm border border-gray-100 p-4">
        <OrderTable orders={filteredOrders} onUpdateStatus={handleUpdateStatus} />
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { useProducts, useCreateProduct, useUpdateProduct, useDeleteProduct, useUpdateProductStock } from '@/hooks/productHooks';
import { ProductDto } from '@/types/product';
import { ProductTable } from '@/components/admin/product/ProductTable';
import { ProductForm } from '@/components/admin/product/ProductForm';
import { DeleteConfirmationDialog } from '@/components/admin/shared/DeleteConfirmationDialog';
import { toast } from 'sonner';
import { Skeleton } from '@/components/ui/skeleton';

export default function AdminProductsPage() {
  const { data: products, isLoading, isError, error } = useProducts();
  const { mutate: createProduct } = useCreateProduct();
  const { mutate: updateProduct } = useUpdateProduct();
  const { mutate: deleteProduct } = useDeleteProduct();
  const { mutate: updateProductStock } = useUpdateProductStock();

  const [isFormOpen, setIsFormOpen] = useState<boolean>(false);
  const [editingProduct, setEditingProduct] = useState<ProductDto | null>(null);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState<boolean>(false);
  const [productToDelete, setProductToDelete] = useState<ProductDto | null>(null);

  const handleAddProduct = (): void => {
    setEditingProduct(null);
    setIsFormOpen(true);
  };

  const handleEditProduct = (product: ProductDto): void => {
    setEditingProduct(product);
    setIsFormOpen(true);
  };

  const handleDeleteProduct = (product: ProductDto): void => {
    setProductToDelete(product);
    setIsDeleteDialogOpen(true);
  };

  const handleConfirmDelete = (): void => {
    if (productToDelete) {
      deleteProduct(productToDelete.id, {
        onSuccess: () => {
          toast.success('Product deleted successfully.');
          setIsDeleteDialogOpen(false);
          setProductToDelete(null);
        },
        onError: (err) => {
          toast.error(`Failed to delete product: ${err.message}`);
        },
      });
    }
  };

  const handleUpdateStock = (product: ProductDto, newQuantity: number): void => {
    updateProductStock({ productId: product.id, request: { stockQuantity: newQuantity } }, {
      onSuccess: () => {
        toast.success('Product stock updated successfully.');
      },
      onError: (err) => {
        toast.error(`Failed to update stock: ${err.message}`);
      },
    });
  };

  const handleFormSubmit = (data: ProductDto): void => {
    if (editingProduct) {
      updateProduct({ productId: editingProduct.id, request: data }, {
        onSuccess: () => {
          toast.success('Product updated successfully.');
          setIsFormOpen(false);
          setEditingProduct(null);
        },
        onError: (err) => {
          toast.error(`Failed to update product: ${err.message}`);
        },
      });
    } else {
      createProduct(data, {
        onSuccess: () => {
          toast.success('Product created successfully.');
          setIsFormOpen(false);
        },
        onError: (err) => {
          toast.error(`Failed to create product: ${err.message}`);
        },
      });
    }
  };

  if (isLoading) {
    return (
      <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-6">Product Management</h1>
        <div className="flex justify-end mb-4">
          <Skeleton className="h-10 w-40" />
        </div>
        <Skeleton className="h-[500px] w-full" />
      </div>
    );
  }

  if (isError) {
    return (
      <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-6">Product Management</h1>
        <p className="text-red-500">Error loading products: {error?.message}</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
      <h1 className="text-3xl font-bold text-gray-900 mb-6">Product Management</h1>
      <div className="flex justify-end mb-4">
        <Button onClick={handleAddProduct} data-testid="add-product-cta">Add New Product</Button>
      </div>
      <ProductTable
        products={products || []}
        onEdit={handleEditProduct}
        onDelete={handleDeleteProduct}
        onUpdateStock={handleUpdateStock}
      />

      <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
        <DialogContent className="sm:max-w-[600px]">
          <DialogHeader>
            <DialogTitle>{editingProduct ? 'Edit Product' : 'Add New Product'}</DialogTitle>
          </DialogHeader>
          <ProductForm
            initialData={editingProduct}
            onSubmit={handleFormSubmit}
            onCancel={() => setIsFormOpen(false)}
          />
        </DialogContent>
      </Dialog>

      <DeleteConfirmationDialog
        isOpen={isDeleteDialogOpen}
        onClose={() => setIsDeleteDialogOpen(false)}
        onConfirm={handleConfirmDelete}
        itemToDeleteName={productToDelete?.name || 'product'}
      />
    </div>
  );
}

import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { useEvents, useCreateEvent, useUpdateEvent, useDeleteEvent } from '@/hooks/eventHooks';
import { EventTable } from '@/components/admin/event/EventTable';
import { EventForm } from '@/components/admin/event/EventForm';
import { DeleteConfirmationDialog } from '@/components/admin/shared/DeleteConfirmationDialog';
import { EventDto } from '@/types/event';
import { toast } from 'sonner';
import { Loader2 } from 'lucide-react';

export default function AdminEventsPage(): React.JSX.Element {
  const { data: events, isLoading, isError, error } = useEvents();
  const createEventMutation = useCreateEvent();
  const updateEventMutation = useUpdateEvent();
  const deleteEventMutation = useDeleteEvent();

  const [isFormOpen, setIsFormOpen] = useState<boolean>(false);
  const [editingEvent, setEditingEvent] = useState<EventDto | null>(null);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState<boolean>(false);
  const [eventToDelete, setEventToDelete] = useState<EventDto | null>(null);

  const handleAddEvent = (): void => {
    setEditingEvent(null);
    setIsFormOpen(true);
  };

  const handleEditEvent = (event: EventDto): void => {
    setEditingEvent(event);
    setIsFormOpen(true);
  };

  const handleDeleteEvent = (event: EventDto): void => {
    setEventToDelete(event);
    setIsDeleteDialogOpen(true);
  };

  const confirmDeleteEvent = (): void => {
    if (eventToDelete) {
      deleteEventMutation.mutate(eventToDelete.id, {
        onSuccess: () => {
          toast.success('Event deleted successfully!');
          setIsDeleteDialogOpen(false);
          setEventToDelete(null);
        },
        onError: (err) => {
          toast.error(`Failed to delete event: ${err.message}`);
        },
      });
    }
  };

  const handleFormSubmit = (data: EventDto): void => {
    if (editingEvent) {
      updateEventMutation.mutate(
        { eventId: editingEvent.id, request: data },
        {
          onSuccess: () => {
            toast.success('Event updated successfully!');
            setIsFormOpen(false);
            setEditingEvent(null);
          },
          onError: (err) => {
            toast.error(`Failed to update event: ${err.message}`);
          },
        }
      );
    } else {
      createEventMutation.mutate(data, {
        onSuccess: () => {
          toast.success('Event created successfully!');
          setIsFormOpen(false);
        },
        onError: (err) => {
          toast.error(`Failed to create event: ${err.message}`);
        },
      });
    }
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  if (isError) {
    return <div className="text-center text-red-500">Error loading events: {error?.message}</div>;
  }

  return (
    <div className="max-w-7xl mx-auto py-6 sm:px-6 lg:px-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-gray-900">Manage Events</h1>
        <Button onClick={handleAddEvent} data-testid="add-event-cta">
          Add New Event
        </Button>
      </div>

      <EventTable events={events || []} onEdit={handleEditEvent} onDelete={handleDeleteEvent} />

      <Dialog open={isFormOpen} onOpenChange={setIsFormOpen}>
        <DialogContent className="sm:max-w-[600px]">
          <DialogHeader>
            <DialogTitle>{editingEvent ? 'Edit Event' : 'Create New Event'}</DialogTitle>
          </DialogHeader>
          <EventForm
            initialData={editingEvent}
            onSubmit={handleFormSubmit}
            onCancel={() => setIsFormOpen(false)}
          />
        </DialogContent>
      </Dialog>

      <DeleteConfirmationDialog
        isOpen={isDeleteDialogOpen}
        onClose={() => setIsDeleteDialogOpen(false)}
        onConfirm={confirmDeleteEvent}
        itemToDeleteName={eventToDelete?.name || 'event'}
      />
    </div>
  );
}
